1	import { ed25519 } from "@noble/curves/ed25519.js";
2	import { compareBytes, decodeCanonical, encodeCanonical, hashDomain } from "@ts-drp/canonical";
3	
4	import type { CurrentAnchorTrust } from "./index.js";
5	import {
6		type CreatorIssuanceRetirementSigningRequest,
7		mintCreatorIssuanceRetirementSigningRequest,
8	} from "./internal/creator-issuance-retirement-signing-request.js";
9	import { resolveCreatorAnchorTrustMaterial } from "./internal/seal-authority-custody.js";
10	
11	export const CREATOR_AUTHOR_ISSUANCE_FRONTIERS_KIND = "drp-creator-author-issuance-frontiers-state" as const;
12	export const CREATOR_AUTHOR_ISSUANCE_FRONTIERS_MAX_RECORD_BYTES = 8192 as const;
13	export const CREATOR_AUTHOR_ISSUANCE_FRONTIERS_GENESIS_SENTINEL = hex(
14		hashDomain(
15			"ts-drp/creator-author-issuance-frontiers/genesis/v1",
16			encodeCanonical({ kind: "drp-creator-author-issuance-frontiers-genesis", version: 1 })
17		)
18	);
19	
20	const DOMAIN = "ts-drp/creator-author-issuance-frontiers/v1";
21	const DIGEST = /^[0-9a-f]{64}$/u;
22	const OBJECT_ID = /^[A-Za-z0-9._:-]{1,256}$/u;
23	const PREIMAGE_KEYS = Object.freeze([
24		"closedAnchorDigest",
25		"closedEpoch",
26		"commitQcRef",
27		"currentAclDigest",
28		"cutValueDigest",
29		"frontiers",
30		"genesisAnchorDigest",
31		"kind",
32		"objectId",
33		"priorAggregateCandidateDigest",
34		"protocolMajor",
35		"snapshotManifestDigest",
36		"successorAclDigest",
37		"successorAnchorDigest",
38		"successorEpoch",
39		"version",
40	] as const);
41	const RECORD_KEYS = Object.freeze([...PREIMAGE_KEYS, "detachedCreatorSignature"] as const);
42	const OPEN_KEYS = Object.freeze([
43		"exactCanonicalRecordBytes",
44		"expectedCommitQcRef",
45		"expectedCurrentAclDigest",
46		"expectedCutValueDigest",
47		"expectedSnapshotManifestDigest",
48		"expectedSuccessorAclDigest",
49		"floorTrust",
50	] as const);
51	const OPEN_KEYS_WITH_CURRENT = Object.freeze([...OPEN_KEYS, "currentTrust"] as const);
52	const PREPARE_KEYS = Object.freeze([
53		"commitQcRef",
54		"currentAclDigest",
55		"currentTrust",
56		"cutValueDigest",
57		"frontiers",
58		"priorAggregateCandidateDigest",
59		"snapshotManifestDigest",
60		"successorAclDigest",
61		"successorTrust",
62	] as const);
63	
64	export type CreatorAuthorIssuanceFrontier = readonly [author: string, admittedAuthorSequence: number | null];
65	
66	export interface CreatorAuthorIssuanceFrontiersRef {
67		readonly byteLength: number;
68		readonly digest: string;
69	}
70	
71	export interface CreatorAuthorIssuanceFrontiersIdentity {
72		readonly closedAnchorDigest: string;
73		readonly closedEpoch: number;
74		readonly commitQcRef: CreatorAuthorIssuanceFrontiersRef;
75		readonly currentAclDigest: string;
76		readonly cutValueDigest: string;
77		readonly frontiers: readonly CreatorAuthorIssuanceFrontier[];
78		readonly genesisAnchorDigest: string;
79		readonly objectId: string;
80		readonly priorAggregateCandidateDigest: string;
81		readonly snapshotManifestDigest: string;
82		readonly successorAclDigest: string;
83		readonly successorAnchorDigest: string;
84		readonly successorEpoch: number;
85	}
86	
87	export interface CreatorAuthorIssuanceFrontiersPreparation {
88		readonly __creatorAuthorIssuanceFrontiersPreparation?: never;
89	}
90	
91	export interface VerifiedCreatorAuthorIssuanceFrontiers {
92		readonly __verifiedCreatorAuthorIssuanceFrontiers?: never;
93	}
94	
95	interface PreparationState {
96		readonly digest: Uint8Array;
97		readonly preimage: Readonly<Record<string, unknown>>;
98		readonly publicKey: Uint8Array;
99	}
100	
101	const preparations = new WeakMap<CreatorAuthorIssuanceFrontiersPreparation, PreparationState>();
102	const verified = new WeakMap<VerifiedCreatorAuthorIssuanceFrontiers, CreatorAuthorIssuanceFrontiersIdentity>();
103	
104	function hex(bytes: Uint8Array): string {
105		return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
106	}
107	
108	function plainRecord(value: unknown): value is Readonly<Record<string, unknown>> {
109		if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
110		const prototype = Object.getPrototypeOf(value);
111		return prototype === Object.prototype || prototype === null;
112	}
113	
114	function exactKeys(value: Readonly<Record<string, unknown>>, keys: readonly string[]): boolean {
115		const actual = Reflect.ownKeys(value);
116		return (
117			actual.length === keys.length &&
118			actual.every((key) => typeof key === "string" && keys.includes(key)) &&
119			keys.every((key) => {
120				const descriptor = Object.getOwnPropertyDescriptor(value, key);
121				return descriptor?.enumerable === true && "value" in descriptor;
122			})
123		);
124	}
125	
126	function safeSequence(value: unknown): value is number {
127		return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
128	}
129	
130	function anchorAclDigest(exactCanonicalAnchorPreimageBytes: Uint8Array): string | undefined {
131		try {
132			const decoded = decodeCanonical(exactCanonicalAnchorPreimageBytes);
133			return plainRecord(decoded) && typeof decoded.aclDigest === "string" && DIGEST.test(decoded.aclDigest)
134				? decoded.aclDigest
135				: undefined;
136		} catch {
137			return undefined;
138		}
139	}
140	
141	function validRef(value: unknown): value is CreatorAuthorIssuanceFrontiersRef {
142		return (
143			plainRecord(value) &&
144			exactKeys(value, ["byteLength", "digest"]) &&
145			typeof value.byteLength === "number" &&
146			Number.isSafeInteger(value.byteLength) &&
147			value.byteLength > 0 &&
148			typeof value.digest === "string" &&
149			DIGEST.test(value.digest)
150		);
151	}
152	
153	function exactFrontier(value: unknown): CreatorAuthorIssuanceFrontier | undefined {
154		if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype || value.length !== 2) return undefined;
155		const keys = Reflect.ownKeys(value);
156		if (keys.length !== 3 || !keys.includes("0") || !keys.includes("1") || !keys.includes("length")) return undefined;
157		const author = value[0];
158		const sequence = value[1];
159		return typeof author === "string" && DIGEST.test(author) && (sequence === null || safeSequence(sequence))
160			? Object.freeze([author, sequence] as const)
161			: undefined;
162	}
163	
164	function copiedFrontiers(value: unknown): readonly CreatorAuthorIssuanceFrontier[] | undefined {
165		if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype || value.length > 64) {
166			return undefined;
167		}
168		const keys = Reflect.ownKeys(value);
169		if (
170			keys.length !== value.length + 1 ||
171			!keys.includes("length") ||
172			value.some((_entry, index) => !keys.includes(String(index)))
173		) {
174			return undefined;
175		}
176		const output: CreatorAuthorIssuanceFrontier[] = [];
177		let previous = "";
178		for (const entry of value) {
179			const selected = exactFrontier(entry);
180			if (selected === undefined || selected[0] <= previous) return undefined;
181			previous = selected[0];
182			output.push(selected);
183		}
184		return Object.freeze(output);
185	}
186	
187	function validRecordFields(record: Readonly<Record<string, unknown>>): boolean {
188		return (
189			record.kind === CREATOR_AUTHOR_ISSUANCE_FRONTIERS_KIND &&
190			record.protocolMajor === 3 &&
191			record.version === 1 &&
192			typeof record.objectId === "string" &&
193			OBJECT_ID.test(record.objectId) &&
194			typeof record.genesisAnchorDigest === "string" &&
195			DIGEST.test(record.genesisAnchorDigest) &&
196			safeSequence(record.closedEpoch) &&
197			typeof record.closedAnchorDigest === "string" &&
198			DIGEST.test(record.closedAnchorDigest) &&
199			safeSequence(record.successorEpoch) &&
200			record.successorEpoch === record.closedEpoch + 1 &&
201			typeof record.successorAnchorDigest === "string" &&
202			DIGEST.test(record.successorAnchorDigest) &&
203			typeof record.currentAclDigest === "string" &&
204			DIGEST.test(record.currentAclDigest) &&
205			typeof record.successorAclDigest === "string" &&
206			DIGEST.test(record.successorAclDigest) &&
207			typeof record.cutValueDigest === "string" &&
208			DIGEST.test(record.cutValueDigest) &&
209			validRef(record.commitQcRef) &&
210			typeof record.snapshotManifestDigest === "string" &&
211			DIGEST.test(record.snapshotManifestDigest) &&
212			typeof record.priorAggregateCandidateDigest === "string" &&
213			DIGEST.test(record.priorAggregateCandidateDigest) &&
214			copiedFrontiers(record.frontiers) !== undefined
215		);
216	}
217	
218	function identity(record: Readonly<Record<string, unknown>>): CreatorAuthorIssuanceFrontiersIdentity {
219		const ref = record.commitQcRef as CreatorAuthorIssuanceFrontiersRef;
220		return Object.freeze({
221			closedAnchorDigest: record.closedAnchorDigest as string,
222			closedEpoch: record.closedEpoch as number,
223			commitQcRef: Object.freeze({ byteLength: ref.byteLength, digest: ref.digest }),
224			currentAclDigest: record.currentAclDigest as string,
225			cutValueDigest: record.cutValueDigest as string,
226			frontiers: copiedFrontiers(record.frontiers) as readonly CreatorAuthorIssuanceFrontier[],
227			genesisAnchorDigest: record.genesisAnchorDigest as string,
228			objectId: record.objectId as string,
229			priorAggregateCandidateDigest: record.priorAggregateCandidateDigest as string,
230			snapshotManifestDigest: record.snapshotManifestDigest as string,
231			successorAclDigest: record.successorAclDigest as string,
232			successorAnchorDigest: record.successorAnchorDigest as string,
233			successorEpoch: record.successorEpoch as number,
234		});
235	}
236	
237	function copiedIdentity(value: CreatorAuthorIssuanceFrontiersIdentity): CreatorAuthorIssuanceFrontiersIdentity {
238		return Object.freeze({
239			...value,
240			commitQcRef: Object.freeze({ ...value.commitQcRef }),
241			frontiers: Object.freeze(
242				value.frontiers.map((entry) => Object.freeze([...entry]) as CreatorAuthorIssuanceFrontier)
243			),
244		});
245	}
246	
247	function failure(reason: string): Readonly<{ ok: false; reason: string }> {
248		return Object.freeze({ ok: false as const, reason });
249	}
250	
251	/**
252	 * Prepares one creator-signed bounded current-writer issuance frontier.
253	 * @param input - Authenticated adjacent trust floors and exact close identities.
254	 * @returns One-use signing preparation or a closed failure.
255	 */
256	export function prepareCreatorAuthorIssuanceFrontiers(input: unknown): Readonly<
257		| { ok: false; reason: string }
258		| {
259				digest: string;
260				exactCanonicalPreimageBytes: Uint8Array;
261				ok: true;
262				preparation: CreatorAuthorIssuanceFrontiersPreparation;
263				signingRequest: CreatorIssuanceRetirementSigningRequest;
264		  }
265	> {
266		try {
267			if (!plainRecord(input) || !exactKeys(input, PREPARE_KEYS)) return failure("MALFORMED_INPUT");
268			const current = resolveCreatorAnchorTrustMaterial(input.currentTrust as CurrentAnchorTrust);
269			const successor = resolveCreatorAnchorTrustMaterial(input.successorTrust as CurrentAnchorTrust);
270			const frontiers = copiedFrontiers(input.frontiers);
271			if (
272				current === undefined ||
273				successor === undefined ||
274				frontiers === undefined ||
275				current.objectId !== successor.objectId ||
276				current.genesisAnchorDigest !== successor.genesisAnchorDigest ||
277				successor.currentEpoch !== current.currentEpoch + 1 ||
278				compareBytes(current.publicKey, successor.publicKey) !== 0 ||
279				input.currentAclDigest !== anchorAclDigest(current.exactCanonicalCurrentAnchorPreimageBytes) ||
280				input.successorAclDigest !== anchorAclDigest(successor.exactCanonicalCurrentAnchorPreimageBytes)
281			) {
282				return failure("TRUST_INVALID");
283			}
284			const preimage = Object.freeze({
285				closedAnchorDigest: current.currentAnchorDigest,
286				closedEpoch: current.currentEpoch,
287				commitQcRef: plainRecord(input.commitQcRef)
288					? Object.freeze({ byteLength: input.commitQcRef.byteLength, digest: input.commitQcRef.digest })
289					: input.commitQcRef,
290				currentAclDigest: input.currentAclDigest,
291				cutValueDigest: input.cutValueDigest,
292				frontiers,
293				genesisAnchorDigest: current.genesisAnchorDigest,
294				kind: CREATOR_AUTHOR_ISSUANCE_FRONTIERS_KIND,
295				objectId: current.objectId,
296				priorAggregateCandidateDigest: input.priorAggregateCandidateDigest,
297				protocolMajor: 3,
298				snapshotManifestDigest: input.snapshotManifestDigest,
299				successorAclDigest: input.successorAclDigest,
300				successorAnchorDigest: successor.currentAnchorDigest,
301				successorEpoch: successor.currentEpoch,
302				version: 1,
303			});
304			if (!validRecordFields(preimage)) return failure("IDENTITY_INVALID");
305			const exactCanonicalPreimageBytes = encodeCanonical(preimage);
306			const digest = hashDomain(DOMAIN, exactCanonicalPreimageBytes);
307			const preparation = Object.freeze({}) as CreatorAuthorIssuanceFrontiersPreparation;
308			preparations.set(
309				preparation,
310				Object.freeze({ digest: Uint8Array.from(digest), preimage, publicKey: Uint8Array.from(current.publicKey) })
311			);
312			return Object.freeze({
313				digest: hex(digest),
314				exactCanonicalPreimageBytes: Uint8Array.from(exactCanonicalPreimageBytes),
315				ok: true as const,
316				preparation,
317				signingRequest: mintCreatorIssuanceRetirementSigningRequest(digest),
318			});
319		} catch {
320			return failure("MALFORMED_INPUT");
321		}
322	}
323	
324	/**
325	 * Completes and size-bounds one prepared frontier record.
326	 * @param input - Opaque preparation and detached creator signature.
327	 * @returns Exact canonical record bytes or a closed failure.
328	 */
329	export function completeCreatorAuthorIssuanceFrontiers(
330		input: unknown
331	): Readonly<{ exactCanonicalRecordBytes: Uint8Array; ok: true } | { ok: false; reason: string }> {
332		try {
333			if (!plainRecord(input) || !exactKeys(input, ["detachedSignature", "preparation"])) {
334				return failure("MALFORMED_INPUT");
335			}
336			const state = preparations.get(input.preparation as CreatorAuthorIssuanceFrontiersPreparation);
337			preparations.delete(input.preparation as CreatorAuthorIssuanceFrontiersPreparation);
338			if (state === undefined) return failure("PREPARATION_UNAVAILABLE");
339			if (!(input.detachedSignature instanceof Uint8Array) || input.detachedSignature.byteLength !== 64) {
340				return failure("SIGNATURE_INVALID");
341			}
342			const signature = Uint8Array.from(input.detachedSignature);
343			if (!ed25519.verify(signature, state.digest, state.publicKey, { zip215: false })) {
344				return failure("SIGNATURE_INVALID");
345			}
346			const exactCanonicalRecordBytes = encodeCanonical({
347				...state.preimage,
348				detachedCreatorSignature: signature,
349			});
350			return exactCanonicalRecordBytes.byteLength > CREATOR_AUTHOR_ISSUANCE_FRONTIERS_MAX_RECORD_BYTES
351				? failure("RECORD_TOO_LARGE")
352				: Object.freeze({ exactCanonicalRecordBytes: Uint8Array.from(exactCanonicalRecordBytes), ok: true as const });
353		} catch {
354			return failure("MALFORMED_INPUT");
355		}
356	}
357	
358	/**
359	 * Opens one exact frontier record against an independently authenticated successor floor.
360	 * @param input - Exact record, close identities, and authenticated successor floor.
361	 * @returns Opaque verified capability or a closed failure.
362	 */
363	export function openCreatorAuthorIssuanceFrontiers(
364		input: unknown
365	): Readonly<{ capability: VerifiedCreatorAuthorIssuanceFrontiers; ok: true } | { ok: false; reason: string }> {
366		try {
367			if (
368				!plainRecord(input) ||
369				(!exactKeys(input, OPEN_KEYS) && !exactKeys(input, OPEN_KEYS_WITH_CURRENT)) ||
370				!(input.exactCanonicalRecordBytes instanceof Uint8Array) ||
371				input.exactCanonicalRecordBytes.byteLength > CREATOR_AUTHOR_ISSUANCE_FRONTIERS_MAX_RECORD_BYTES
372			) {
373				return failure("MALFORMED_INPUT");
374			}
375			const bytes = Uint8Array.from(input.exactCanonicalRecordBytes);
376			const decoded = decodeCanonical(bytes, { maxBytes: CREATOR_AUTHOR_ISSUANCE_FRONTIERS_MAX_RECORD_BYTES });
377			if (
378				!plainRecord(decoded) ||
379				!exactKeys(decoded, RECORD_KEYS) ||
380				compareBytes(encodeCanonical(decoded), bytes) !== 0 ||
381				!validRecordFields(decoded) ||
382				!(decoded.detachedCreatorSignature instanceof Uint8Array)
383			) {
384				return failure("RECORD_INVALID");
385			}
386			const floor = resolveCreatorAnchorTrustMaterial(input.floorTrust as CurrentAnchorTrust);
387			const current =
388				"currentTrust" in input ? resolveCreatorAnchorTrustMaterial(input.currentTrust as CurrentAnchorTrust) : undefined;
389			const ref = decoded.commitQcRef as CreatorAuthorIssuanceFrontiersRef;
390			if (
391				floor === undefined ||
392				("currentTrust" in input && current === undefined) ||
393				(current !== undefined &&
394					(current.objectId !== floor.objectId ||
395						current.genesisAnchorDigest !== floor.genesisAnchorDigest ||
396						current.currentEpoch + 1 !== floor.currentEpoch ||
397						current.currentAnchorDigest !== decoded.closedAnchorDigest ||
398						current.currentEpoch !== decoded.closedEpoch ||
399						compareBytes(current.publicKey, floor.publicKey) !== 0 ||
400						decoded.currentAclDigest !== anchorAclDigest(current.exactCanonicalCurrentAnchorPreimageBytes))) ||
401				decoded.objectId !== floor.objectId ||
402				decoded.genesisAnchorDigest !== floor.genesisAnchorDigest ||
403				decoded.successorEpoch !== floor.currentEpoch ||
404				decoded.successorAnchorDigest !== floor.currentAnchorDigest ||
405				decoded.successorAclDigest !== anchorAclDigest(floor.exactCanonicalCurrentAnchorPreimageBytes) ||
406				decoded.currentAclDigest !== input.expectedCurrentAclDigest ||
407				decoded.successorAclDigest !== input.expectedSuccessorAclDigest ||
408				decoded.cutValueDigest !== input.expectedCutValueDigest ||
409				decoded.snapshotManifestDigest !== input.expectedSnapshotManifestDigest ||
410				!validRef(input.expectedCommitQcRef) ||
411				ref.byteLength !== input.expectedCommitQcRef.byteLength ||
412				ref.digest !== input.expectedCommitQcRef.digest
413			) {
414				return failure("IDENTITY_INVALID");
415			}
416			const { detachedCreatorSignature: signature, ...preimage } = decoded;
417			const digest = hashDomain(DOMAIN, encodeCanonical(preimage));
418			if (signature.byteLength !== 64 || !ed25519.verify(signature, digest, floor.publicKey, { zip215: false })) {
419				return failure("SIGNATURE_INVALID");
420			}
421			const capability = Object.freeze({}) as VerifiedCreatorAuthorIssuanceFrontiers;
422			verified.set(capability, identity(decoded));
423			return Object.freeze({ capability, ok: true as const });
424		} catch {
425			return failure("MALFORMED_INPUT");
426		}
427	}
428	
429	/**
430	 * Resolves detached verified identity from a genuine opaque frontier capability.
431	 * @param capability - Capability returned by openCreatorAuthorIssuanceFrontiers.
432	 * @returns A detached frozen identity or undefined for foreign custody.
433	 */
434	export function resolveCreatorAuthorIssuanceFrontiers(
435		capability: VerifiedCreatorAuthorIssuanceFrontiers
436	): CreatorAuthorIssuanceFrontiersIdentity | undefined {
437		const selected = verified.get(capability);
438		return selected === undefined ? undefined : copiedIdentity(selected);
439	}

