418	async function authorIssuanceFrontiersCandidate(
419		input: Readonly<{
420			current: InspectedHead;
421			currentAclDigest: string;
422			currentExactAclBytes: Uint8Array;
423			currentTrust: CurrentAnchorTrust;
424			cutValueDigest: string;
425			graph: Exclude<ReturnType<V3CreatorCloseRegistration["captureCloseGraph"]>, undefined>;
426			issuanceScope: DurableIssueScope;
427			issuanceStore: DurableIssuanceStore;
428			legacy: Awaited<ReturnType<typeof issuanceRetirementCandidate>>;
429			qcRef: GenerationRef;
430			signer: FinalitySigner;
431			snapshotManifestDigest: string;
432			successorAclDigest: string;
433			successorExactAclBytes: Uint8Array;
434			successorTrust: CurrentAnchorTrust;
435		}>
