308	function authenticatedRetirementPair(input: InspectCreatorTransitionAdvanceInput):
309		| Readonly<{
310				readonly current?: DetachedClosureCandidate;
311				readonly currentIdentity?: CreatorIssuanceRetirementIdentity;
312				readonly proposed: DetachedClosureCandidate;
313				readonly proposedIdentity: CreatorIssuanceRetirementIdentity;
314		  }>
315		| undefined {
316		if (
