318			input.successorTrust.currentEpoch !== input.currentTrust.currentEpoch + 1 ||
319			input.currentTrust.objectId !== input.successorTrust.objectId ||
320			input.currentTrust.genesisAnchorDigest !== input.successorTrust.genesisAnchorDigest ||
321			input.proofRefs.length !== 2
