328			return undefined;
329		}
330		const proposedRetirement = proposedMatches[0] as DetachedClosureCandidate;
331		if (!exactClosureOccurrence(input.proposed.closure, proposedRetirement)) return undefined;
332		if (
333			currentMatches.length === 1 &&
334			!exactClosureOccurrence(input.current.closure, currentMatches[0] as DetachedClosureCandidate)
335		) {
336			return undefined;
337		}
338		const proposedCut = input.proposed.candidates.find((candidate) =>
339			sameRef(candidate.ref, input.proofRefs[0] as GenerationRef)
340		);
341		const proposedQc = input.proposed.candidates.find((candidate) =>
342			sameRef(candidate.ref, input.proofRefs[1] as GenerationRef)
343		);
344		if (proposedCut === undefined || proposedQc === undefined) return undefined;
345		const openedProposed = openedRetirement(proposedRetirement, input.successorTrust, proposedCut, proposedQc);
346		if (
347			openedProposed === undefined ||
348			openedProposed.identity.closedEpoch !== input.currentTrust.currentEpoch ||
349			openedProposed.identity.closedAnchorDigest !== input.currentTrust.currentAnchorDigest
350		) {
351			return undefined;
352		}
353		if (input.currentTrust.currentEpoch === 0) {
354			return openedProposed.identity.priorAdmittedAuthorSequence === null &&
355				openedProposed.identity.priorRetirementCandidateDigest === CREATOR_ISSUANCE_RETIREMENT_GENESIS_SENTINEL
