357				: undefined;
358		}
359		const currentCandidate = currentMatches[0] as DetachedClosureCandidate;
360		const retiringCut = uniqueCandidate(
361			input.current.candidates,
362			"drp-hard-epoch-cut",
363			input.currentTrust.currentEpoch - 1
364		);
365		const retiringQc = uniqueCandidate(
366			input.current.candidates,
367			"drp-seal-qc",
368			input.currentTrust.currentEpoch - 1,
369			"commit"
370		);
371		if (retiringCut === undefined || retiringQc === undefined) return undefined;
372		const openedCurrent = openedRetirement(currentCandidate, input.currentTrust, retiringCut, retiringQc);
373		return openedCurrent !== undefined &&
374			openedProposed.identity.author === openedCurrent.identity.author &&
375			openedProposed.identity.priorRetirementCandidateDigest === currentCandidate.ref.digest &&
376			openedProposed.identity.priorAdmittedAuthorSequence === openedCurrent.identity.admittedAuthorSequence &&
377			openedProposed.identity.admittedAuthorSequence >= openedCurrent.identity.admittedAuthorSequence
378			? Object.freeze({
379					current: currentCandidate,
380					currentIdentity: openedCurrent.identity,
381					proposed: openedProposed.candidate,
382					proposedIdentity: openedProposed.identity,
383				})
384			: undefined;
