400		if (!exactClosureOccurrence(input.proposed.closure, proposed)) return undefined;
401		const proposedCut = input.proposed.candidates.find((candidate) =>
402			sameRef(candidate.ref, input.proofRefs[0] as GenerationRef)
403		);
404		const proposedQc = input.proposed.candidates.find((candidate) =>
