412			openedProposed === undefined ||
413			openedProposed.identity.closedEpoch !== input.currentTrust.currentEpoch ||
414			openedProposed.identity.closedAnchorDigest !== input.currentTrust.currentAnchorDigest
415		) {
416			return undefined;
417		}
418		const legacyFrontier = openedProposed.identity.frontiers.find(
