420		);
421		if (legacyFrontier !== undefined && legacyFrontier[1] !== retirement.proposedIdentity.admittedAuthorSequence) {
422			return undefined;
423		}
424		if (currentMatches.length === 0) {
425			return openedProposed.identity.priorAggregateCandidateDigest === CREATOR_AUTHOR_ISSUANCE_FRONTIERS_GENESIS_SENTINEL
426				? Object.freeze({ proposed })
427				: undefined;
428		}
429		const current = currentMatches[0] as DetachedClosureCandidate;
430		if (!exactClosureOccurrence(input.current.closure, current)) return undefined;
431		const closedEpoch = input.currentTrust.currentEpoch - 1;
432		const currentCut = uniqueCandidate(input.current.candidates, "drp-hard-epoch-cut", closedEpoch);
433		const currentQc = uniqueCandidate(input.current.candidates, "drp-seal-qc", closedEpoch, "commit");
434		const currentAcl = uniqueCandidate(input.current.candidates, "drp-v3-latched-acl", closedEpoch);
435		if (currentCut === undefined || currentQc === undefined || currentAcl === undefined) return undefined;
436		const openedCurrent = openedAggregate(current, input.currentTrust, currentCut, currentQc, { acl: currentAcl });
437		if (openedCurrent === undefined || openedProposed.identity.priorAggregateCandidateDigest !== current.ref.digest) {
438			return undefined;
439		}
440		const proposedByAuthor = new Map(openedProposed.identity.frontiers);
441		for (const [author, boundary] of openedCurrent.identity.frontiers) {
442			const next = proposedByAuthor.get(author);
443			if (next !== undefined && boundary !== null && (next === null || next < boundary)) return undefined;
444		}
445		return Object.freeze({ current, proposed });
446	}
