448	/**
449	 * Selects the compatibility or bounded transition predicate and owns stale-ref derivation.
450	 * @param input - Current/proposed closure pair, new proof refs, and staging/verification mode.
451	 * @returns The authenticated proposal (normalized only for in-memory staging) or a rejection.
452	 */
453	export function inspectCreatorTransitionAdvance(
454		input: InspectCreatorTransitionAdvanceInput
455	): InspectCreatorTransitionAdvanceResult {
456		try {
457			const retirement = authenticatedRetirementPair(input);
458			if (retirement === undefined) return failure("TRUST_CLOSURE_INVALID");
459			const aggregate = authenticatedAggregatePair(input, retirement);
460			if (aggregate === undefined) return failure("TRUST_CLOSURE_INVALID");
461			const withoutControlCandidates = (
462				closure: CreatorTransitionClosure,
463				candidates: readonly (DetachedClosureCandidate | undefined)[]
464			): CreatorTransitionClosure =>
465				Object.freeze({
466					candidates: Object.freeze(
467						closure.candidates.filter(
468							(item) => !candidates.some((candidate) => candidate !== undefined && sameRef(item.ref, candidate.ref))
469						)
470					),
471					closure: Object.freeze(
472						closure.closure.filter(
473							(ref) => !candidates.some((candidate) => candidate !== undefined && sameRef(ref, candidate.ref))
474						)
475					),
476				});
477			const normalizedCurrent = withoutControlCandidates(input.current, [retirement.current, aggregate.current]);
478			const normalizedProposed = withoutControlCandidates(input.proposed, [retirement.proposed, aggregate.proposed]);
479			const trustCandidates = input.current.candidates.filter(
480				(candidate) => record(candidate)?.kind === "drp-anchor-trust-state"
481			);
482			if (trustCandidates.length !== 1) return failure("TRUST_CLOSURE_INVALID");
483			const trust = record(trustCandidates[0] as DetachedClosureCandidate);
484			if (typeof trust?.currentEpoch !== "number" || !Number.isSafeInteger(trust.currentEpoch)) {
485				return failure("TRUST_CLOSURE_INVALID");
486			}
487			if (trust.currentEpoch === 0) {
488				const result = inspectCreatorTrustAdvance({
489					current: normalizedCurrent,
490					proofRefs: input.proofRefs,
491					proposed: normalizedProposed,
492				});
493				return result.ok
494					? Object.freeze({ kind: result.kind, ok: true as const, proposed: input.proposed })
495					: failure(result.reason);
496			}
497			const retiringEpoch = trust.currentEpoch - 1;
498			const retiringCut = uniqueCandidate(input.current.candidates, "drp-hard-epoch-cut", retiringEpoch);
499			const retiringQc = uniqueCandidate(input.current.candidates, "drp-seal-qc", retiringEpoch, "commit");
500			const retiringAcl = uniqueCandidate(input.current.candidates, "drp-v3-latched-acl", retiringEpoch);
501			if (retiringCut === undefined || retiringQc === undefined || retiringAcl === undefined) {
502				return failure("RETIRING_PROOF_REFS_INVALID");
503			}
504			const retiring = new Set([retiringCut.ref.digest, retiringQc.ref.digest, retiringAcl.ref.digest]);
505			const proposedWithoutRetiring =
506				input.mode === "stage"
507					? Object.freeze({
508							candidates: Object.freeze(
509								normalizedProposed.candidates.filter((candidate) => !retiring.has(candidate.ref.digest))
510							),
511							closure: Object.freeze(
512								normalizedProposed.closure.filter((ref) => !retiring.has(ref.digest)).sort(compareRef)
513							),
514						})
515					: normalizedProposed;
516			const result = inspectBoundedCreatorTrustAdvance({
517				current: normalizedCurrent,
518				proofRefs: input.proofRefs,
519				proposed: proposedWithoutRetiring,
520				retiringPredecessorAclRef: retiringAcl.ref,
521				retiringProofRefs: [retiringCut.ref, retiringQc.ref],
522			});
523			if (!result.ok) return failure(result.reason);
524			const proposed =
525				input.mode === "verify"
526					? input.proposed
527					: Object.freeze({
528							candidates: Object.freeze(
529								[...proposedWithoutRetiring.candidates, retirement.proposed, aggregate.proposed].sort((left, right) =>
530									compareRef(left.ref, right.ref)
531								)
532							),
533							closure: Object.freeze(
534								[...proposedWithoutRetiring.closure, retirement.proposed.ref, aggregate.proposed.ref].sort(compareRef)
535							),
536						});
537			return Object.freeze({ kind: result.kind, ok: true as const, proposed });
538		} catch {
539			return failure("TRUST_CLOSURE_INVALID");
540		}
541	}

