11	export const D110C_0C1F1_MULTI_AUTHOR_FRONTIER_CARRIER_REQUIRED =
12		"D110C_0C1F1_MULTI_AUTHOR_FRONTIER_CARRIER_REQUIRED" as const;
13	export const D110C_0C1F1_FRONTIER_KIND = "drp-creator-author-issuance-frontiers-state" as const;
14	export const D110C_0C1F1_LEGACY_KIND = "drp-creator-issuance-retirement-state" as const;
