16	function canonicalRecord(bytes: Uint8Array): Readonly<Record<string, unknown>> {
17		const decoded = decodeCanonical(bytes);
18		if (decoded === null || typeof decoded !== "object" || Array.isArray(decoded)) {
19			throw new TypeError("D110C_0C1F2_CANONICAL_RECORD_INVALID");
20		}
21		return decoded as Readonly<Record<string, unknown>>;
22	}
