24	/**
25	 * Proves that a genuine two-writer close admits both authors but current
26	 * production emits only the creator's legacy issuance carrier.
27	 * @returns Completion after the aggregate frontier is authenticated.
28	 */
29	export async function proveD110c0c1f2MissingMultiAuthorFrontier(): Promise<void> {
30		const authorities = d108d1bChatAuthorities();
31		const creator = authorities.find(({ id }) => id === "alice");
32		const secondWriter = authorities.find(({ id }) => id === "bob");
33		if (creator === undefined || secondWriter === undefined) {
34			throw new TypeError("D110C_0C1F2_TWO_WRITER_AUTHORITY_UNAVAILABLE");
35		}
36		const fixture = await openGenuineCreatorAdoptionFixture({
37			authorizedPrivateKeySeedHexes: [creator.privateKeySeedHex, secondWriter.privateKeySeedHex],
38			establishedPeerPrivateKeySeedHex: secondWriter.privateKeySeedHex,
39		});
40		try {
41			const {
42				closeResult,
43				currentTrust,
44				establishedPeer,
45				journalRows,
46				localIssued,
47				predecessorExactCanonicalLatchedAclBytes,
48				proposed,
49			} = fixture.evidence;
50			if (
51				closeResult.ok !== true ||
52				closeResult.epoch !== 0 ||
53				closeResult.successorEpoch !== 1 ||
54				establishedPeer?.author !== secondWriter.author ||
55				establishedPeer.authorSequence !== 0
56			) {
57				throw new TypeError("D110C_0C1F2_GENUINE_TWO_WRITER_CLOSE_INVALID");
58			}
59			const acl = canonicalRecord(predecessorExactCanonicalLatchedAclBytes);
60			const members = Array.isArray(acl.members)
61				? acl.members.map((member) => member as Readonly<Record<string, unknown>>)
62				: [];
63			if (
64				acl.permissionless !== false ||
65				members.length !== 2 ||
66				!members.every(
67					(member) =>
68						Array.isArray(member.groups) &&
69						member.groups.includes("writer") &&
70						(member.author === creator.author || member.author === secondWriter.author)
71				)
72			) {
73				throw new TypeError("D110C_0C1F2_TWO_WRITER_ACL_INVALID");
74			}
75			const admittedSecondWriterRows = journalRows.filter((row) => {
76				if (row.sourceKind !== "received" || row.vertexDigest !== Buffer.from(establishedPeer.digest).toString("hex")) {
77					return false;
78				}
79				const vertex = canonicalRecord(row.exactCanonicalPreimageBytes);
80				return vertex.author === secondWriter.author && vertex.authorSequence === 0;
81			});
82			if (admittedSecondWriterRows.length !== 1) {
83				throw new TypeError("D110C_0C1F2_SECOND_WRITER_ADMISSION_INVALID");
84			}
85			const records = proposed.candidates.map(({ bytes }) => canonicalRecord(bytes));
86			const legacy = records.filter(({ kind }) => kind === D110C_0C1F1_LEGACY_KIND);
87			const aggregate = records.filter(({ kind }) => kind === D110C_0C1F1_FRONTIER_KIND);
88			if (
89				legacy.length !== 1 ||
90				legacy[0]?.author !== creator.author ||
91				proposed.references.length !== proposed.candidates.length
92			) {
93				throw new TypeError("D110C_0C1F2_CURRENT_CLOSURE_CLASS_INVALID");
94			}
95			if (aggregate.length === 0) throw new TypeError(D110C_0C1F1_MULTI_AUTHOR_FRONTIER_CARRIER_REQUIRED);
96			if (aggregate.length !== 1) throw new TypeError("D110C_0C1F2_AGGREGATE_CANDIDATE_AMBIGUOUS");
97			const candidate = proposed.candidates.find(
98				({ bytes }) => canonicalRecord(bytes).kind === D110C_0C1F1_FRONTIER_KIND
99			);
100			const cut = proposed.candidates.find(({ ref }) => ref.digest === closeResult.cutValueRef.digest);
101			const qc = proposed.candidates.find(({ ref }) => ref.digest === closeResult.commitQcRef.digest);
102			const trust = proposed.candidates.find(({ ref }) => ref.digest === closeResult.successorTrustRef.digest);
103			if (candidate === undefined || cut === undefined || qc === undefined || trust === undefined) {
104				throw new TypeError("D110C_0C1F2_AGGREGATE_PROOF_UNAVAILABLE");
105			}
106			const successor = openCreatorSuccessorTrust({
107				currentTrust,
108				exactCanonicalCommitQcBytes: qc.bytes,
109				exactCanonicalCutValueBytes: cut.bytes,
110				exactCanonicalTrustStateRecordBytes: trust.bytes,
111			});
112			if (!successor.ok) throw new TypeError("D110C_0C1F2_SUCCESSOR_TRUST_UNAVAILABLE");
113			const aggregateRecord = canonicalRecord(candidate.bytes);
114			const cutRecord = canonicalRecord(cut.bytes);
115			const opened = openCreatorAuthorIssuanceFrontiers({
116				currentTrust,
117				exactCanonicalRecordBytes: candidate.bytes,
118				expectedCommitQcRef: qc.ref,
119				expectedCurrentAclDigest: Buffer.from(
120					hashDomain("ts-drp/latched-acl/v3", predecessorExactCanonicalLatchedAclBytes)
121				).toString("hex"),
122				expectedCutValueDigest: Buffer.from(hashDomain("ts-drp/hard-epoch-cut/v3", cut.bytes)).toString("hex"),
123				expectedSnapshotManifestDigest: cutRecord.snapshotManifestDigest,
124				expectedSuccessorAclDigest: aggregateRecord.successorAclDigest,
125				floorTrust: successor.trust,
126			});
127			const identity = opened.ok ? resolveCreatorAuthorIssuanceFrontiers(opened.capability) : undefined;
128			if (identity === undefined) throw new TypeError("D110C_0C1F2_AGGREGATE_OPEN_FAILED");
129			const expectedFrontiers = [
130				[creator.author, localIssued.authorSequence] as const,
131				[secondWriter.author, establishedPeer.authorSequence] as const,
132			].sort(([left], [right]) => left.localeCompare(right));
133			if (JSON.stringify(identity.frontiers) !== JSON.stringify(expectedFrontiers)) {
134				throw new TypeError(
135					`D110C_0C1F2_AGGREGATE_FRONTIERS_INVALID:${JSON.stringify(identity.frontiers)}:${JSON.stringify(expectedFrontiers)}`
136				);
137			}
138			if (process.env.D110C_0C1F2_RECORD_EVIDENCE === "1") {
139				process.stdout.write(
140					`D110C_0C1F2_PROTOCOL_RED_EVIDENCE=${JSON.stringify({
141						aggregateCarrierCount: aggregate.length,
142						closeSetCount: fixture.evidence.history.closeSetCount,
143						creator: creator.author,
144						legacyCarrierCount: legacy.length,
145						secondWriter: secondWriter.author,
146						secondWriterAdmittedRows: admittedSecondWriterRows.length,
147						successorEpoch: closeResult.successorEpoch,
148						writerCount: members.length,
149					})}\n`
150				);
151			}
152		} finally {
153			await fixture.close();
154		}
155	}

